/* @lc app=leetcode id=3534 lang=kotlin */ class Solution { fun ub(a: List<Int>, v: Int): Int = generateSequence(0 to a.size) { (lo, hi) -> if (lo >= hi) null else ((lo + hi) / 2).let { m -> if (a[m] <= v) m + 1 to hi else lo to m } }.last().first fun pathExistenceQueries(n: Int, nums: IntArray, maxDiff: Int, queries: Array<IntArray>): IntArray = nums.indices.sortedBy { nums[it] }.let { ord -> IntArray(n).also { rk -> ord.forEachIndexed { i, v -> rk[v] = i } }.let { rk -> ord.map { nums[it] }.let { vs -> IntArray(n) { p -> ub(vs, vs[p] + maxDiff) - 1 }.let { nx -> Array(17) { IntArray(n) }.also { up -> nx.copyInto(up[0]) }.also { up -> (1 until 17).forEach { k -> (0 until n).forEach { p -> up[k][p] = up[k - 1][up[k - 1][p]] } } }.let { up -> queries.map { (u, v) -> if (u == v) 0 else (minOf(rk[u], rk[v]) to maxOf(rk[u], rk[v])).let { (a, b) -> (16 downTo 0).fold(a to 0) { (pos, cnt), k -> if (up[k][pos] < b) up[k][pos] to cnt + (1 shl k) else pos to cnt }.let { (pos, cnt) -> if (nx[pos] >= b) cnt + 1 else -1 } } }.toIntArray() } } } } } }